import{_ as s,l as i,o as e,c as l,v as r,p as n,x as o,d,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"ARIES 三阶段与 CLR","description":"","frontmatter":{"title":"ARIES 三阶段与 CLR","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/aries-phases-clr.md","filePath":"cs/aries-phases-clr.md","lastUpdated":1789023840000}'),c={name:"cs/aries-phases-clr.md"};function h(A,a,S,_,L,R){const t=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="aries-三阶段与-clr" tabindex="-1">ARIES 三阶段与 CLR <a class="header-anchor" href="#aries-三阶段与-clr" aria-label="Permalink to &quot;ARIES 三阶段与 CLR&quot;">​</a></h1><div class="epigraph"><p>分析从检查点重建脏页表与事务表；重做从最早脏页 LSN 前滚到日志尾；撤销从尾部按事务链补偿。CLR 让撤销本身可重做且不嵌套撤销。</p><footer>—— 据 Mohan, Haderle, Lindsay, Pirahesh and Schwarz, ARIES, TODS 1992；主干 ARIES 直觉的播放补全</footer></div><p>并发续在 <a href="/cs/calvin-deterministic">Calvin</a> 封口。本课打开恢复与复制续：主干 <a href="/cs/aries-recovery">ARIES 直觉</a> 已给 steal/no-force 与生理日志。缺口是崩溃后的三阶段与补偿日志记录（CLR）：撤销中途再崩溃时，不能对 UNDO 再 UNDO 成指数。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>模糊检查点后，页可能落后或超前于数据文件。分析：从最近检查点扫到日志尾，重建 dirty page table（每页 recoveryLSN）与事务表（未决事务 lastLSN）。重做：从 \\(\\min\\) recoveryLSN 起，对每条 redo，若页上 pageLSN 更旧则应用——幂等靠 pageLSN。撤销：未决事务沿 prevLSN 链反向，写 CLR（描述已做的补偿），CLR 的 UndoNxtLSN 跳过已补偿段。</p><p>缺口是 <strong>CLR 的「永不撤销 CLR」</strong>：再崩溃时重做 CLR 即可，不必嵌套补偿。这是 ARIES 相对朴素 UNDO 的关键。</p><p><span class="marginnote">Mohan et al. TODS 1992。生理：页内物理 redo、逻辑 undo（如 B+ 补偿）。本课不把每条索引 SMO 的 CLR 写完。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>启动：读控制文件找检查点 → 分析 → redo → undo → 开放新事务。日志尾可能半条记录，要校验。并行 redo 按页分流，页内仍按 LSN 序。</p><p>与 doublewrite：重做前先修好撕裂页，否则 pageLSN 不可信。</p>',10)),(e(),n(E,null,{default:o(()=>[p(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20CK%5B%22%E6%A3%80%E6%9F%A5%E7%82%B9%22%5D%20--%3E%20AN%5B%22%E5%88%86%E6%9E%90%3A%20%E8%84%8F%E9%A1%B5%E8%A1%A8%E4%B8%8E%E4%BA%8B%E5%8A%A1%E8%A1%A8%22%5D%0A%20%20AN%20--%3E%20RD%5B%22%E4%BB%8E%20min%20recoveryLSN%20%E9%87%8D%E5%81%9A%22%5D%0A%20%20RD%20--%3E%20UN%5B%22%E6%B2%BF%E9%93%BE%E6%92%A4%E9%94%80%E6%9C%AA%E5%86%B3%E4%BA%8B%E5%8A%A1%22%5D%0A%20%20UN%20--%3E%20CLR%5B%22%E5%86%99%20CLR%20%E4%B8%8D%E5%B5%8C%E5%A5%97%E6%92%A4%E9%94%80%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>事务回滚（运行时 abort）与崩溃 undo 走同一补偿思想。保存点是链上的标记，rollback to 停在标记。组提交后课把多事务 LSN 一起刷。</p><p>复制：物理复制本质是把 redo 送到备库再应用，类似只要 redo 阶段。逻辑复制解成行，后课。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲模糊检查点如何边刷脏边写。也不把影子分页混进 ARIES。日志粒度下一课之后。</p><p>后课默认：恢复=分析+redo+undo+CLR。模糊检查点：缩短分析与 redo 起点而不停更新。</p><p>pageLSN 是重做幂等的钉子。没有它，生理 redo 不敢下手。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>三阶段重建表、前滚、补偿撤销。</li><li>CLR 使撤销可重做且不递归撤销。</li><li>模糊检查点下一课。</li><li>出处：Mohan et al. ARIES, TODS 1992；Gray and Reuter。</li></ul>',9))])}const C=s(c,[["render",h]]);export{m as __pageData,C as default};
